const REPO = 'ibb142/ivx-holdings-platform';
const { execSync } = await import('child_process');

// 1. Verify token
const res = await fetch('https://api.github.com/user', {
  headers: { Authorization: `token ${TOKEN}`, 'User-Agent': 'ivx-deploy' },
});
const data = await res.json();
console.log(`1. TOKEN VERIFY: HTTP ${res.status} — login=${data.login || data.message}`);
if (!data.login) process.exit(1);

// 2. Check GitHub main SHA before push
const branchRes = await fetch(`https://api.github.com/repos/${REPO}/branches/main`, {
  headers: { Authorization: `token ${TOKEN}`, 'User-Agent': 'ivx-deploy' },
});
const branchData = await branchRes.json();
const ghShaBefore = branchData.commit?.sha;
console.log(`2. GITHUB main BEFORE: ${ghShaBefore?.slice(0,12) || branchData.message}`);

// 3. Check local state
const localHead = execSync('git rev-parse HEAD', { cwd: '/home/user/rork-app', encoding: 'utf-8' }).trim();
const rorkOrigin = execSync('git rev-parse origin/main', { cwd: '/home/user/rork-app', encoding: 'utf-8' }).trim();
console.log(`3. LOCAL HEAD: ${localHead.slice(0,12)}`);
console.log(`   RORK origin/main: ${rorkOrigin.slice(0,12)}`);
console.log(`   GITHUB main: ${ghShaBefore?.slice(0,12)}`);

// 4. Add GitHub as a new remote (keep rork remote intact)
try {
  execSync('git remote remove github', { cwd: '/home/user/rork-app', stdio: 'pipe' });
} catch {}
execSync(`git remote add github https://${TOKEN}@github.com/${REPO}.git`, { cwd: '/home/user/rork-app' });
console.log('4. REMOTE "github" added');

// 5. Push to GitHub — force to ensure full sync
console.log('5. PUSHING to GitHub main...');
try {
  const pushOut = execSync('git push github main --force 2>&1', { 
    cwd: '/home/user/rork-app', encoding: 'utf-8', timeout: 60000 
  });
  console.log(`   PUSH OUTPUT: ${pushOut.trim()}`);
} catch (e) {
  console.log(`   PUSH ERROR: ${e.message?.slice(0, 300)}`);
  // Try without force
  try {
    const pushOut2 = execSync('git push github main 2>&1', { 
      cwd: '/home/user/rork-app', encoding: 'utf-8', timeout: 60000 
    });
    console.log(`   PUSH OUTPUT (no force): ${pushOut2.trim()}`);
  } catch (e2) {
    console.log(`   PUSH FAILED BOTH WAYS: ${e2.message?.slice(0, 300)}`);
    process.exit(1);
  }
}

// 6. Verify GitHub SHA after push
const branchRes2 = await fetch(`https://api.github.com/repos/${REPO}/branches/main`, {
  headers: { Authorization: `token ${TOKEN}`, 'User-Agent': 'ivx-deploy' },
});
const branchData2 = await branchRes2.json();
const ghShaAfter = branchData2.commit?.sha;
console.log(`6. GITHUB main AFTER: ${ghShaAfter?.slice(0,12)}`);

// 7. SHA parity check
if (ghShaAfter === localHead) {
  console.log(`\n✅ SHA PARITY ACHIEVED`);
  console.log(`   Local HEAD    = ${localHead}`);
  console.log(`   GitHub main   = ${ghShaAfter}`);
  console.log(`   MATCH: YES`);
} else {
  console.log(`\n⚠️ SHA MISMATCH`);
  console.log(`   Local HEAD    = ${localHead}`);
  console.log(`   GitHub main   = ${ghShaAfter}`);
}

// 8. Count files in repo on GitHub
const treeRes = await fetch(`https://api.github.com/repos/${REPO}/git/trees/${ghShaAfter}?recursive=1`, {
  headers: { Authorization: `token ${TOKEN}`, 'User-Agent': 'ivx-deploy' },
});
const treeData = await treeRes.json();
console.log(`\n7. REPO FILE COUNT: ${treeData.tree?.length || 'unknown'} files on GitHub`);
console.log(`   Truncated: ${treeData.truncated}`);

// 9. Remove the token-bearing remote so it's not in git config
execSync('git remote remove github', { cwd: '/home/user/rork-app', stdio: 'pipe' });
console.log('8. REMOTE "github" removed (token cleaned from git config)');

console.log('\n=== DEPLOYMENT COMPLETE ===');
